document.querySelectorAll('[data-copy-url]').forEach((button)=>{button.addEventListener('click',async()=>{const value=button.dataset.copyUrl||'';const status=button.parentElement.querySelector('[data-copy-status]');let ok=false;try{await navigator.clipboard.writeText(value);ok=true}catch{const area=document.createElement('textarea');area.value=value;area.setAttribute('readonly','');area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();ok=document.execCommand('copy');area.remove()}status.textContent=ok?'MCP URL copied.':'Copy failed. Select the URL above.';button.textContent=ok?'Copied':'Copy MCP URL';setTimeout(()=>{button.textContent='Copy MCP URL'},1800)})});